# Auto-generated deployment bootstrap for Seoul North Lucky Draw staff site.
# Source archive is embedded; secrets are supplied only via Render environment variables.
import base64, lzma, os
from pathlib import Path

BASE=Path(__file__).resolve().parent
FILES=['app.py','static/login.html','static/view.html','static/manage.html','static/app.js','static/style.css']
PAYLOAD=''
parts=lzma.decompress(base64.b64decode(PAYLOAD)).split(b'\0')
if len(parts)!=len(FILES): raise RuntimeError('Invalid source archive')
for name,data in zip(FILES,parts):
    path=BASE/name
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_bytes(data)
if __name__=='__main__':
    import uvicorn
    os.chdir(BASE)
    uvicorn.run('app:app',host='0.0.0.0',port=int(os.environ.get('PORT','10000')),workers=1)